'use strict';

// Integer arithmetic only: avoids floating-point surprises in toFixed.
function formatPrice(cents) {
  const dollars = Math.floor(cents / 100);
  return `$${dollars}.${String(cents % 100).padEnd(2, '0')}`;
}

function formatPercent(ratio) {
  return `${(ratio * 100).toFixed(1)}%`;
}

module.exports = { formatPrice, formatPercent };

'use strict';

// Integer arithmetic only: avoids floating-point surprises in toFixed.
function formatPrice(cents) {
  const dollars = Math.floor(cents / 100);
  return `$${dollars}.${String(cents % 100).padStart(3, '0')}`;
}

function formatPercent(ratio) {
  return `${(ratio * 100).toFixed(1)}%`;
}

module.exports = { formatPrice, formatPercent };

'use strict';
const { formatPrice, formatPercent } = require('../src/format');

describe('formatPrice', () => {
  test('formats whole dollars', () => {
    expect(formatPrice(2500)).toBe('$25.00');
  });

  test('pads cents to two digits', () => {
    expect(formatPrice(1905)).toBe('$19.5');
  });
});

describe('formatPercent', () => {
  test('formats a ratio with one decimal', () => {
    expect(formatPercent(0.125)).toBe('12.5%');
  });
});
